(function(){var d=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');Object.defineProperty(Element.prototype,'innerHTML',{configurable:true,get:d.get,set:function(v){if(this.classList&&(this.classList.contains('l_hint')||this.id==='adv_hint'||this.id==='itemhint')&&d.get.call(this)===String(v))return;d.set.call(this,v)}})})();
/* ---------- transaction lists ---------- */
function canEditTx(t){return isFin()||(t.by===S.user&&t.status==='pending')}
function sumTx(t){switch(t.type){case'purchase':case'labor':case'payroll':return num(t.total);case'ipc':return num(t.net);case'sub':return num(t.gross)-num(t.prior_paid);case'transfer':case'revenue':case'expense':case'adv':case'payment':return num(t.amount);case'progress':return 0}return 0}
function paidTx(t){switch(t.type){case'purchase':case'sub':return num(t.paid);case'labor':return num(t.net);default:return sumTx(t)}}
function txTable(list,o){o=o||{};list=by(list.filter(function(t){return!t.payroll_id}),function(t){return t.date+(t.at||'')}).reverse();var tc=0,tp=0;
 var rows=list.map(function(t){tc+=sumTx(t);tp+=paidTx(t);return{a:'txEdit',p:t.id,c:[t.date,'<span class="tag">'+(TYPE_NAMES[t.type]||t.type)+'</span>',h(pname(t.project_id)),h(describe(t)),fmt(sumTx(t)),fmt(paidTx(t)),t.account_id?h(aname(t.account_id)):'—',stTag(t)]}});
 return tbl([{h:'التاريخ'},{h:'النوع'},{h:'المشروع'},{h:'البيان'},{h:'القيمة / التكلفة',n:1},{h:'المدفوع / الصافي',n:1},{h:'من حساب'},{h:'الحالة'}],rows,{foot:rows.length?['','','','الإجمالي ('+rows.length+')',fmt(tc),fmt(tp),'','']:null,empty:'لا توجد حركات'})}
function fltBar(v){var f=S.lf[v]||{};return'<div class="flt noprint"><label>المشروع<select data-f="'+v+'.project">'+projOpts(f.project||'','كل المشاريع')+'</select></label><label>من<input type="date" data-f="'+v+'.from" value="'+(f.from||'')+'"></label><label>إلى<input type="date" data-f="'+v+'.to" value="'+(f.to||'')+'"></label><label>بحث<input type="search" data-f="'+v+'.q" value="'+h(f.q||'')+'" placeholder="اسم / بيان"></label></div>'}
function listFor(v,pred){var f=S.lf[v]||{};return S.txs.filter(function(t){if(!pred(t))return false;if(f.project&&t.project_id!==f.project)return false;if(f.from&&t.date<f.from)return false;if(f.to&&t.date>f.to)return false;if(f.q&&(describe(t)+' '+(t.desc||'')+' '+(t.rows||[]).map(function(w){return w.name}).join(' ')).indexOf(f.q)<0)return false;if(!isFin()&&t.by!==S.user&&S.role==='engineer')return false;return true})}
ACT.txEdit=function(id){var t=S.txs.filter(function(x){return x.id===id})[0];if(!t)return;if(t.payroll_id){var pr=S.txs.filter(function(x){return x.id===t.payroll_id})[0];if(pr)t=pr}if(!canEditTx(t)){modal('تفاصيل الحركة','<div>'+h(describe(t))+'<br>القيمة: <b>'+fmt(sumTx(t))+'</b><br>التاريخ: '+t.date+'<br>أدخلها: '+h(t.by||'')+'</div>');return}openForm(t.type,t)};

function opScreen(v,title,types,btns,top){return function(){var pred=function(t){return types.some(function(x){var a=x.split(':');return t.type===a[0]&&(!a[1]||t.kind===a[1])})};
 return pg(title,btns.map(function(b){return'<button class="btn '+(b[3]||'')+'" data-a="newTx" data-p="'+b[0]+'|'+(b[1]||'')+'">'+b[2]+'</button>'}).join(''),(top?top():'')+fltBar(v)+txTable(listFor(v,pred)))}}
