function conForm(c,after){modal(c?'تعديل مقاول':'مقاول جديد','<div class="fg">'+fld('اسم المقاول',inp('c_name',c?c.name:''))+fld('التخصص',inp('c_trade',c?c.trade:'','text','placeholder="تكييف / كهرباء / سباكة / دهانات..."'))+fld('الهاتف',inp('c_phone',c?c.phone:'','tel'))+fld('رصيد افتتاحي مستحق له (قبل بدء استخدام النظام)',inp('c_open',c?c.open:'','number','step="any"'))+'</div>',{extra:c&&isFin()?'<button class="btn d" data-a="conDel" data-p="'+c.id+'" style="margin-inline-end:auto">حذف</button>':'',save:async function(){var n=v$('c_name').trim();if(!n){toast('اكتب الاسم');return false}var o=c||{id:uid()};o.name=n;o.trade=v$('c_trade');o.phone=v$('c_phone');o.open=num(v$('c_open'));if(!c)S.cfg.contractors.push(o);if(!await saveCfg())return false;if(after)after(o);render()}})}
ACT.conDel=async function(id){var n=S.txs.filter(function(t){return t.party_id===id}).length;if(n){toast('لا يمكن حذف مقاول عليه '+n+' حركة');return}if(!confirm('حذف المقاول؟'))return;S.cfg.contractors=S.cfg.contractors.filter(function(c){return c.id!==id});await saveCfg();closeModal();render()};

/* ---------- save / approve ---------- */
function nextSubNo(pid,con,excl){var m=0,n=0;S.txs.forEach(function(x){if(x.type!=='sub'||x.project_id!==pid||x.party_id!==con||x.id===excl)return;n++;var k=parseInt(String(x.no||'').replace(/\D/g,''),10);if(k>m)m=k});return String(Math.max(m,n)+1)}
function conItems(con,pid){var o={};S.txs.forEach(function(t){if(!con||t.party_id!==con||(pid&&t.project_id!==pid))return;if(t.type==='sub')(t.lines||[]).forEach(function(l){var k=l.boq_id||('n:'+(l.name||''));if(!l.boq_id&&!l.name)return;o[k]={boq_id:l.boq_id||'',name:l.name||'',date:t.date}})});var c=S.cfg.contractors.filter(function(x){return x.id===con})[0];var L=Object.keys(o).map(function(k){return o[k]});if(!L.length&&c&&c.trade&&pid&&S.txs.some(function(t){return t.type==='sub'&&t.party_id===con&&t.project_id===pid}))L.push({boq_id:'',name:c.trade,date:''});return L}
async function saveTx(o,existing){if(o.type==='sub'&&!String(o.no||'').trim()&&o.project_id&&o.party_id)o.no=nextSubNo(o.project_id,o.party_id,existing&&existing.id);if(typeof closedBlock==='function'&&(closedBlock(o.date)||(existing&&closedBlock(existing.date)))){toast('الفترة مقفلة حتى '+S.cfg.closedTo+' — لا يمكن إضافة أو تعديل حركة فيها');return false}if(!existing){o.id=uid();o.by=S.user;o.at=new Date().toISOString();o.status=(isFin()||o.type==='progress')?'approved':'pending'}else{o.id=existing.id;o.by=existing.by;o.at=existing.at;o.status=existing.status||'approved';if(existing.demo)o.demo=true;['adv_of','imp_site','imp_key','imp_boq','src','src_file','custody','imp_batch'].forEach(function(k){if(existing[k]!=null&&o[k]==null)o[k]=existing[k]})}
 if(o.status==='approved'||(!existing&&(isFin()||o.type==='progress'))){var _old={};if(existing&&existing.status!=='pending')cashMoves(existing).forEach(function(m){_old[m.acc]=(_old[m.acc]||0)+m.amt});var _bad=[];var _seen={};cashMoves(o).forEach(function(m){if(m.amt>=0||_seen[m.acc])return;_seen[m.acc]=1;var ac=acc(m.acc);if(!ac)return;var tot=sum(cashMoves(o).filter(function(q){return q.acc===m.acc}),function(q){return q.amt});var nb=accStats(ac).bal-(_old[m.acc]||0)+tot;if(nb<-0.5&&nb<accStats(ac).bal)_bad.push(ac.name+' ← '+fmt(nb))});if(_bad.length&&!confirm('⚠ هذه الحركة تجعل الرصيد بالسالب:\n'+_bad.join('\n')+'\n\nهل تريد المتابعة؟ (يُفضّل تمويل الحساب أولًا بتحويل داخلي)'))return false}
 if(!existing&&S.addBatch&&o.type!=='transfer'){o.imp_batch=S.addBatch}
 o.updated=new Date().toISOString();if(!await dbSet('txs',o))return false;if(existing){S.txs=S.txs.map(function(x){return x.id===o.id?o:x})}else S.txs.push(o);if(ensureReg(o))await saveCfg();if(o.type==='revenue'&&o.adv_of){var pj=proj(o.adv_of);if(pj&&num(pj.advance)!==num(o.amount)){pj.advance=num(o.amount);await dbSet('projects',pj)}}render();toast(o.status==='pending'?'تم الإرسال للمحاسب للاعتماد':'تم الحفظ');return true}
function delBtn(t){return t&&canEditTx(t)?'<button class="btn d" data-a="txDel" data-p="'+t.id+'" style="margin-inline-end:auto">حذف</button>'+((t.type==='payment'||t.type==='sub')?'<button class="btn" data-a="txCancel" data-p="'+t.id+'">إلغاء / عكس</button>':''):''}
ACT.txDel=async function(id){var tc=S.txs.filter(function(x){return x.id===id})[0];if(tc&&closedBlock(tc.date)){toast('الفترة مقفلة حتى '+S.cfg.closedTo);return}if(!confirm('حذف هذه الحركة نهائيًا؟'))return;if(tc&&(tc.type==='sub'||tc.type==='payment'||tc.type==='adv')){var _rs=prompt('سبب الحذف (يُسجَّل في سجل المراجعة):')||'';S.cfg.auditLog=(S.cfg.auditLog||[]).concat([{by:S.user,at:new Date().toISOString(),op:'delete',type:tc.type,id:tc.id,date:tc.date,amount:sumTx(tc),proj:tc.project_id||'',party:tc.party_id||tc.party||'',reason:_rs}]).slice(-300);await saveCfg()}var _cp=tc&&tc.type==='sub'&&tc.cum?[tc.project_id,tc.party_id]:null;var tt0=S.txs.filter(function(x){return x.id===id})[0];if(tt0&&tt0.type==='payroll'){for(var ch of S.txs.filter(function(x){return x.payroll_id===id}))await dbDel('txs',ch.id);S.txs=S.txs.filter(function(x){return x.payroll_id!==id})}var dt=S.txs.filter(function(x){return x.id===id})[0];if(await dbDel('txs',id)){if(dt&&dt.adv_of){var pj=proj(dt.adv_of);if(pj){pj.advance=0;await dbSet('projects',pj)}}S.txs=S.txs.filter(function(t){return t.id!==id});if(_cp)await cumRecalc(_cp[0],_cp[1]);closeModal();render()}};
function payBlock(t,amtLabel,amtId,req){var m=t&&t.pay_method||'نقدي';return fld('طريقة الدفع','<select id="f_pm">'+opts(['نقدي','شيك','تحويل بنكي'],m)+'</select>')+fld('من حساب (خزينة / بنك)','<select id="f_acc">'+accOpts(t&&t.account_id||'',req?'— اختر —':'— غير محدد —')+'</select>')+fld('رقم الشيك / مرجع التحويل',inp('f_ref',t?t.ref:''))}
function bindPay(){var pm=$('f_pm');if(!pm)return;var cur0=$('f_acc').value;var f=function(){var k=pm.value==='نقدي'?'cash':'bank';var cur=$('f_acc').value||cur0;var l=S.accounts.filter(function(a){return a.kind===k});if(!l.length)l=S.accounts;if(cur&&!l.some(function(a){return a.id===cur})&&acc(cur))l=l.concat([acc(cur)]);$('f_acc').innerHTML='<option value="">— اختر —</option>'+l.map(function(a){return'<option value="'+h(a.id)+'"'+(a.id===cur?' selected':'')+'>'+h(a.name)+(isFin()?' — '+fmt(accStats(a).bal):'')+'</option>'}).join('')};pm.onchange=function(){cur0='';f()};f()}
function needAcc(amount){if(num(amount)>0&&!v$('f_acc')&&isFin()){toast('اختر الخزينة / البنك الذي تم الصرف منه');return true}return false}
function boqOpts(pid,sel,free){var p=proj(pid);var s='<option value="">— غير مرتبط ببند —</option>';if(p)by(p.boq,function(b){return(b.group||'')+' '+(b.code||'')}).forEach(function(b){s+='<option value="'+h(b.id)+'"'+(b.id===sel?' selected':'')+'>'+h((b.group?b.group+' › ':'')+boqLabel(b))+'</option>'});if(free)s+='<option value="__free"'+(sel==='__free'?' selected':'')+'>— بند آخر (غير مدرج بالمقايسة) —</option>';return s}
function itemHint(pid,bid,addVal,addQty,unit,excl){if(!pid||!bid||bid==='__free')return'';var s=itemState(pid,bid);if(!s)return'';var u=itemUse(pid,bid,excl);var c=u.total,b=s.b;var rest=s.bud-c-addVal;var pq=num(u.pqty[unit||b.unit]||0);
 var t='📌 <b>'+h(boqLabel(b))+'</b> — كمية المقايسة <b>'+fq(b.qty)+' '+h(b.unit||'')+'</b> × فئة '+fmt(b.price)+' = قيمة المقايسة <b>'+fmt(s.val)+'</b>'+(num(b.cost_price)?' | التكلفة المقدرة '+fmt(s.bud):'')+'<br>صُرف حتى الآن: <b>'+fmt(c)+'</b> ('+pct(c,s.bud)+'%)'+(addVal?' + هذا السطر '+fmt(addVal)+' = '+fmt(c+addVal)+' ('+pct(c+addVal,s.bud)+'%)':'')+' | المتبقي: <b>'+fmt(rest)+'</b>';
 if((unit||b.unit)===b.unit&&b.qty){t+='<br>كميات مشتراة سابقًا: '+fq(pq)+(addQty?' + '+fq(addQty)+' = '+fq(pq+addQty):'')+' من '+fq(b.qty)+' '+h(b.unit||'')+' | مقاولون: '+fq(u.subQty)+' | منفذ فعليًا: '+fq(u.progQty)}
 return'<div class="hint '+(rest<0?'b':rest<s.bud*0.15?'w':'')+'">'+t+(rest<0?'<br>⚠ تجاوز التكلفة المقدرة للبند':'')+'</div>'}

/* ---------- forms ---------- */
function openForm(type,t,kind){var F={purchase:fPurchase,payroll:fPayroll,ipc:fIpc,sub:function(t,k){(!t||t.cum)?fSubCert(t):(t.quick)?fSubQuick(t):fSub(t,k)},labor:fLabor,expense:fExpense,revenue:fRevenue,adv:fAdv,payment:fPayment,progress:fProgress,contractor:function(){conForm(null)}}[type];if(F)F(t,kind||(t&&t.kind))}
function lineBox(id,inner,removable){return'<div class="ln" id="'+id+'">'+(removable?'<button class="rm" data-a="rmLine" data-p="'+id+'" title="حذف السطر">✕</button>':'')+inner+'</div>'}
ACT.rmLine=function(id){var e=$(id);if(e){e.remove();if(S.recalc)S.recalc()}};
function dlist(id,arr){return'<datalist id="'+id+'">'+arr.map(function(x){return'<option value="'+h(x)+'">'}).join('')+'</datalist>'}
function bindModalCalc(fn){S.recalc=fn;var b=$('mbody');b.oninput=b.onchange=function(){fn()};fn()}

/* purchases */
function nextInvoice(sup,excl){var mx=0,n=0;S.txs.forEach(function(x){if(x.type!=='purchase'||x.status==='rejected'||x.id===excl||String(x.supplier||'').trim()!==sup)return;n++;var m=String(x.invoice||'').match(/(\d+)\s*$/);if(m)mx=Math.max(mx,parseInt(m[1],10))});return String(Math.max(mx,n)+1)}
/* رفع الفاتورة: Excel/CSV يُقرأ إلى أصناف قابلة للمراجعة، والصور/PDF تُرفق كمرجع */
S.invAtt=[];
function invBar(t){S.invAtt=(t&&t.att)?t.att.slice():[];return'<div class="full" id="invbar" style="grid-column:1/-1"><div class="hint"><b>📎 رفع فاتورة:</b> ملف Excel أو CSV (تُقرأ أصنافها تلقائيًا لتراجعها وتعدّلها)، أو صورة / PDF (تُرفق كمرجع بجوار البيانات). <input type="file" id="inv_file" accept=".xlsx,.xls,.csv,.pdf,image/*" style="margin-top:6px"> <span id="inv_msg"></span><div id="inv_list"></div></div></div>'}
function invAttHtml(){return S.invAtt.map(function(a,i){return'<span style="display:inline-flex;gap:4px;align-items:center;margin:4px 6px 0 0;padding:2px 8px;border:1px solid var(--bd,#ccc);border-radius:6px">'+(/^image/.test(a.t)?'<a href="'+a.d+'" target="_blank"><img src="'+a.d+'" style="height:34px;border-radius:4px"></a>':'<a href="'+a.d+'" download="'+h(a.n)+'">📄 '+h(a.n)+'</a>')+'<button type="button" class="rm2" data-a="invRm" data-p="'+i+'">✕</button></span>'}).join('')}
