  var fillPct=function(){var lp=revLastPct(v$('t_proj'));if(!lp)return;WH_TYPES.forEach(function(w){$('whp_'+w.k).value=lp[w.k]!=null?lp[w.k]:'';st['m_'+w.k]=0});$('t_vop').value=lp.vo!=null?lp.vo:'';st.mv=0};
