document.addEventListener('change',function(ev){var f=ev.target.dataset&&ev.target.dataset.f;if(!f)return;var a=f.split('.');S.lf[a[0]]=S.lf[a[0]]||{};S.lf[a[0]][a[1]]=ev.target.value;render()});

/* ---------- review / approval ---------- */
VIEWS.review=function(){var list=S.txs.filter(function(t){return t.status==='pending'||t.status==='rejected'});if(!isFin())list=list.filter(function(t){return t.by===S.user});list=by(list,function(t){return t.at||t.date}).reverse();
 var rows=list.map(function(t){return{c:[t.date,h(t.by||''),'<span class="tag">'+(TYPE_NAMES[t.type]||'')+'</span>',h(describe(t)),fmt(sumTx(t)),t.account_id?h(aname(t.account_id)):'<span class="tag w">بدون حساب</span>',stTag(t),'<button class="btn sm" data-a="txEdit" data-p="'+t.id+'">'+(isFin()?'مراجعة / تعديل':'تعديل')+'</button>'+(isFin()&&t.status==='pending'?' <button class="btn sm p" data-a="txOk" data-p="'+t.id+'">اعتماد</button> <button class="btn sm d" data-a="txNo" data-p="'+t.id+'">رفض</button>':'')]}});
 return pg('المراجعة والاعتماد',isFin()&&list.some(function(t){return t.status==='pending'})?'<button class="btn p" data-a="txOkAll">اعتماد الكل</button>':'','<div class="hint" style="margin-bottom:10px">الحركات التي يدخلها مهندس الموقع تنتظر هنا ولا تؤثر على الأرصدة والتقارير حتى يعتمدها المحاسب.</div>'+tbl([{h:'التاريخ'},{h:'أدخلها'},{h:'النوع'},{h:'البيان'},{h:'القيمة',n:1},{h:'الحساب'},{h:'الحالة'},{h:''}],rows,{empty:'لا توجد حركات بانتظار الاعتماد ✔'}))};
ACT.txOk=async function(id){var t=S.txs.filter(function(x){return x.id===id})[0];if(cashMoves(Object.assign({},t,{status:'approved'})).length===0&&paidTx(t)>0&&t.type!=='progress'){if(!confirm('هذه الحركة بدون حساب صرف؛ لن تظهر في أي خزينة أو بنك. اعتماد على أي حال؟'))return}t.status='approved';t.approved_by=S.user;if(await dbSet('txs',t))render()};
ACT.txNo=async function(id){var t=S.txs.filter(function(x){return x.id===id})[0];t.status='rejected';if(await dbSet('txs',t))render()};
ACT.txOkAll=async function(){var l=S.txs.filter(function(t){return t.status==='pending'});if(!confirm('اعتماد '+l.length+' حركة؟'))return;for(var t of l){t.status='approved';t.approved_by=S.user;await dbSet('txs',t)}render()};
